'use strict';
const defaultServer=location.hostname.endsWith('.chatgpt.site')?'':(location.protocol==='https:'?'wss://':'ws://')+location.host+'/ws';$('serverAddress').value=defaultServer;
const baseDisconnect=disconnect;disconnect=function(){const link=serverLink;serverLink=null;if(link){link.ws.onclose=null;link.ws.close();}baseDisconnect();networkPlayerId=2;};
const baseSetButtons=setButtons;setButtons=function(){baseSetButtons();if(serverLink?.isOwner){for(const id of ['startButton','playButton','resetButton','pauseButton','mode','stadium','scoreLimit','timeLimit','importStadium','editorButton','recordButton','botDifficulty'])$(id).disabled=!!replay;}$('joinRed').disabled=$('joinBlue').disabled=!!serverLink||!!replay;};
const baseReset=resetMatch;resetMatch=function(play=true){if(!serverLink)return baseReset(play);if(!serverLink.isOwner)return;serverLink.send({type:'configure',mode:['bot','2v2','4v4'].includes($('mode').value)?$('mode').value:'bot',stadium:Utils.exportStadium(stadium),difficulty:settings.difficulty,botLevels:settings.botLevels,teamProfile:settings.teamProfile,scoreLimit:+$('scoreLimit').value,timeLimit:+$('timeLimit').value,started:play,paused:menuOpen});if(menuOpen&&play)menuOwnsPause=true;};
const baseStartStop=startStop;startStop=function(){if(serverLink){if(serverLink.isOwner)serverLink.send({type:started?'stop':'start'});return;}baseStartStop();};$('startButton').onclick=startStop;
const baseTogglePause=togglePause;togglePause=function(){if(serverLink){if(!serverLink.isOwner||!started)return;paused=!paused;releaseInputs();serverLink.send({type:'pause',value:paused});setButtons();return;}baseTogglePause();};
const baseRecord=record;record=function(){if(serverLink){if(serverLink.isOwner)serverLink.send({type:'record'});return;}baseRecord();};$('recordButton').onclick=record;
const baseModeChange=$('mode').onchange;$('mode').onchange=()=>{if(serverLink)resetMatch(started);else baseModeChange();};
function connectServer(create){try{const address=$('serverAddress').value.trim();if(!address)throw Error('Enter a server address.');const url=new URL(address);if(!['ws:','wss:'].includes(url.protocol))throw Error('Use a ws:// or wss:// address.');if(location.protocol==='https:'&&url.protocol!=='wss:')throw Error('HTTPS requires a wss:// server.');disconnect();if(replay)closeReplay();showView('play');const ws=new WebSocket(url),link={ws,isOwner:false,send:data=>{if(ws.readyState===1)ws.send(JSON.stringify(data));}};serverLink=link;ws.binaryType='arraybuffer';$('serverRoomStatus').textContent='Connecting…';
 ws.onopen=()=>link.send({type:'join',create,room:$('serverRoomCode').value.trim(),name:settings.name});ws.onerror=()=>{$('serverRoomStatus').textContent='Could not connect to server.';};ws.onclose=()=>{if(serverLink===link){disconnect();notify('Disconnected.');}};
 ws.onmessage=event=>{if(serverLink!==link)return;if(event.data instanceof ArrayBuffer){try{receiveSnapshot(event.data);}catch{notify('Invalid server snapshot.');}return;}let d;try{d=JSON.parse(event.data);}catch{return;}
 if(d.type==='welcome'){networkPlayerId=d.id;link.isOwner=d.owner===d.id;link.room=d.room;peerRole='guest';net.receivedSequence=0;const shim={readyState:'open',get bufferedAmount(){return ws.bufferedAmount;},send:data=>ws.send(data),close(){}};setupChannel(shim);shim.onopen();$('serverRoomCode').value=d.room;$('connectionText').textContent='Room '+d.room+' · headless server';$('serverRoomStatus').textContent='Connected · Room '+d.room;notify('Room '+d.room+' · Share this code to invite players');setButtons();updateCamera();}
 else if(d.type==='room'){link.isOwner=d.owner===networkPlayerId;$('mode').value=d.mode;settings.difficulty=d.difficulty||'hard';settings.botLevels=d.botLevels||{};$('botDifficulty').value=settings.difficulty;updateRoster();$('connectionText').textContent='Room '+d.room+' · '+d.players+' online'+(link.isOwner?' · Host':'');setButtons();}
 else if(d.type==='error'){$('serverRoomStatus').textContent=d.message;notify(d.message);if(!peerConnected){ws.close();}}
 else if(d.type==='recordingStatus'){$('recordIndicator').hidden=!d.active;$('recordButton').textContent=d.active?'■ Save recording':'● Record';}
 else if(d.type==='recording'){const decoded=atob(d.bytes);saveBlob(Uint8Array.from(decoded,c=>c.charCodeAt(0)),'fuckball-server-'+Date.now()+'.hbr2','application/octet-stream');notify('Replay saved.');}
 else if(d.type==='goal'){beep(650,.22);log((d.team===1?'Red':'Blue')+' scores');}
 else channel?.onmessage?.(event);
 };
 }catch(e){$('serverRoomStatus').textContent=e.message;notify(e.message);}}
$('createServerRoom').onclick=()=>connectServer(true);$('joinServerRoom').onclick=()=>connectServer(false);
const basePlayClick=$('playButton').onclick;$('playButton').onclick=()=>{if(serverLink){if(serverLink.isOwner)resetMatch(true);}else basePlayClick();};
